#!/usr/bin/env node
/**
 * Bundles the injected page runtime (src/injected) into string constants that the
 * native app passes to react-native-webview.
 *
 * Why a build step: Hermes compiles JS to bytecode, so `fn.toString()` cannot be used
 * to serialise page code at runtime. The generated file is committed so Metro/EAS
 * builds do not need esbuild; CI runs `--check` to make sure it is up to date.
 *
 *   node scripts/build-injected.mjs          # write src/injected/generated/bundles.ts
 *   node scripts/build-injected.mjs --check  # fail if the committed file is stale
 */
import { build } from 'esbuild';
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outFile = resolve(root, 'src/injected/generated/bundles.ts');
const check = process.argv.includes('--check');

// Android System WebView on old, un-updated devices can be very old; keep syntax conservative.
const target = ['chrome69', 'safari13'];

async function bundle(entry) {
  const result = await build({
    entryPoints: [resolve(root, entry)],
    bundle: true,
    write: false,
    format: 'iife',
    target,
    platform: 'browser',
    minify: false,
    legalComments: 'none',
    charset: 'utf8',
  });
  return result.outputFiles[0].text;
}

const early = await bundle('src/injected/entries/early.entry.ts');
const main = await bundle('src/injected/entries/main.entry.ts');

const header = '/* eslint-disable */\n// AUTO-GENERATED by scripts/build-injected.mjs — do not edit by hand.\n// Source: src/injected/**. Run `npm run build:injected` after changing it.\n';
const content =
  header +
  `export const EARLY_SCRIPT: string = ${JSON.stringify(early)};\n` +
  `export const MAIN_SCRIPT: string = ${JSON.stringify(main)};\n`;

if (check) {
  const current = existsSync(outFile) ? readFileSync(outFile, 'utf8') : '';
  if (current.replace(/\r\n/g, '\n') !== content) {
    console.error('src/injected/generated/bundles.ts is out of date. Run `npm run build:injected`.');
    process.exit(1);
  }
  console.log('Injected bundles are up to date.');
} else {
  mkdirSync(dirname(outFile), { recursive: true });
  writeFileSync(outFile, content);
  console.log(`Wrote ${outFile} (early ${early.length} B, main ${main.length} B)`);
}
